mapper.insert:
INSERT INTO MES_TM_SCHEDULE_RESULT ( SCHEDULE_DATE, BATCH_NO, ORDER_NO, TREAD_CODE, SAP_MATERIAL_CODE, GLUE_CODE, BASE_GLUE_CODE, WHOLE_GLUE_CODE, GLUE_SEQ, MOUTH_PLATE_CODE, SPEC_SIZE, MACHINE_CODE, UNIT_CONSUME, STOCK_QTY, SUPPLY_TIME, MID_PLAN_QTY, MID_PRODUCE_ORDER, MID_SYS_ANALYSIS, MID_HAND_ANALYSIS, NIGHT_PLAN_QTY, NIGHT_PRODUCE_ORDER, NIGHT_SYS_ANALYSIS, NIGHT_HAND_ANALYSIS, DAY_PLAN_QTY, DAY_PRODUCE_ORDER, DAY_SYS_ANALYSIS, DAY_HAND_ANALYSIS, NEXT_MID_PLAN_QTY, NEXT_MID_PRODUCE_ORDER, NEXT_MID_SYS_ANALYSIS, NEXT_MID_HAND_ANALYSIS, IS_RELEASE, MARK_CLOSE_OUT_TIP, TAIL_FLAG, PRODUCTION_STATUS, REMARK, DATA_VERSION, COMPANY_CODE, FACTORY_CODE ) SELECT * FROM (
SELECT #{item.scheduleDate} AS SCHEDULE_DATE, #{item.batchNo} AS BATCH_NO, #{item.orderNo} AS ORDER_NO, #{item.treadCode} AS TREAD_CODE, #{item.sapMaterialCode} AS SAP_MATERIAL_CODE, #{item.glueCode} AS GLUE_CODE, #{item.baseGlueCode} AS BASE_GLUE_CODE, #{item.wholeGlueCode} AS WHOLE_GLUE_CODE, #{item.glueSeq} AS GLUE_SEQ, #{item.mouthPlateCode} AS MOUTH_PLATE_CODE, #{item.specSize} AS SPEC_SIZE, #{item.machineCode} AS MACHINE_CODE, #{item.unitConsume} AS UNIT_CONSUME, #{item.stockQty} AS STOCK_QTY, #{item.supplyTime} AS SUPPLY_TIME, #{item.midPlanQty} AS MID_PLAN_QTY, #{item.midProduceOrder} AS MID_PRODUCE_ORDER, #{item.midSysAnalysis} AS MID_SYS_ANALYSIS, #{item.midHandAnalysis} AS MID_HAND_ANALYSIS, #{item.nightPlanQty} AS NIGHT_PLAN_QTY, #{item.nightProduceOrder} AS NIGHT_PRODUCE_ORDER, #{item.nightSysAnalysis} AS NIGHT_SYS_ANALYSIS, #{item.nightHandAnalysis} AS NIGHT_HAND_ANALYSIS, #{item.dayPlanQty} AS DAY_PLAN_QTY, #{item.dayProduceOrder} AS DAY_PRODUCE_ORDER, #{item.daySysAnalysis} AS DAY_SYS_ANALYSIS, #{item.dayHandAnalysis} AS DAY_HAND_ANALYSIS, #{item.nextMidPlanQty} AS NEXT_MID_PLAN_QTY, #{item.nextMidProduceOrder} AS NEXT_MID_PRODUCE_ORDER, #{item.nextMidSysAnalysis} AS NEXT_MID_SYS_ANALYSIS, #{item.nextMidHandAnalysis} AS NEXT_MID_HAND_ANALYSIS, '1' AS IS_RELEASE, #{item.markCloseOutTip} AS MARK_CLOSE_OUT_TIP, #{item.tailFlag} AS TAIL_FLAG, #{item.productionStatus} AS PRODUCTION_STATUS, #{item.remark} AS REMARK, #{item.dataVersion} AS DATA_VERSION, #{item.companyCode} AS COMPANY_CODE, #{item.factoryCode} AS FACTORY_CODE
) AS t WHERE NOT EXISTS ( SELECT 1 FROM MES_TM_SCHEDULE_RESULT WHERE SCHEDULE_DATE = t.SCHEDULE_DATE AND MACHINE_CODE = t.MACHINE_CODE AND TREAD_CODE = t.TREAD_CODE AND DATA_VERSION = t.DATA_VERSION )

mapper.delete:
DELETE FROM MES_TM_SCHEDULE_RESULT
WHERE SCHEDULE_DATE = #{scheduleDate}
AND DATA_VERSION = #{dataVersion}

mapper.select:
SELECT SCHEDULE_DATE, MACHINE_CODE, TREAD_CODE, DATA_VERSION
FROM MES_TM_SCHEDULE_RESULT
WHERE

    (SCHEDULE_DATE = #{item.scheduleDate}
     AND MACHINE_CODE = #{item.machineCode}
     AND TREAD_CODE = #{item.treadCode}
     AND DATA_VERSION = #{item.dataVersion})
